import{_ as a,o as s,c as o,j as t}from"./chunks/framework.BdHuibk5.js";const m=JSON.parse('{"title":"境由心生","description":"一年多的时间足以改变很多东西，甚至让人对自己感到陌生。面对空虚、迟滞与摇摆，也许真正要做的，是重新找回自己，找回属于自己的夏天。","frontmatter":{"title":"境由心生","date":"2013-06-07 02:30","category":"diary","tags":["心情","自省"],"slug":"state-of-mind-shapes-the-world","layout":"blog-post","description":"一年多的时间足以改变很多东西，甚至让人对自己感到陌生。面对空虚、迟滞与摇摆，也许真正要做的，是重新找回自己，找回属于自己的夏天。"},"headers":[],"relativePath":"blog/state-of-mind-shapes-the-world.md","filePath":"blog/posts/diary/state-of-mind-shapes-the-world.md","lastUpdated":1789447662000}'),l={name:"blog/state-of-mind-shapes-the-world.md"};function r(d,e,n,p,i,c){return s(),o("div",null,[...e[0]||(e[0]=[t("p",null,"一年多了，一年的时间可以改变很多东西，很多很多，多得甚至于让自己觉得自己很陌生。我不再是从前的我，不同时期的人是会有所不同，但现在的我绝对不是早前预期中的样子。",-1),t("p",null,"变成这样，也许是因为环境，在同一环境中待久了，人会变得狭隘，虽谈不上坐井底之蛙，但毕竟还是会有所影响。也许，是时候换换环境，去呼吸一下新鲜的空气。也许也是因为人吧，别问我是具体哪个人，其实是很多人。多多少少还是会受到影响，没有一年前做事那么坚定有目标。其实我这人还是蛮会多愁善感的，比较情绪化。",-1),t("p",null,"六月份一到，意味着 2013 又过了一半了。想想今年真的没做出什么东西来，每天混日子的节奏，没有任何的紧迫感。学习能力严重下降，学习动力丧失得可以。",-1),t("p",null,"有的时候会突然一阵空虚来袭，把自己惊出一身冷汗。我所能做的，仅仅只是戴上耳机，并且尽量不让自己去想起，尽量去逃避罢了。",-1),t("p",null,"现在我想我所能做的，就是面对现实，脚踏实地，不去痴心妄想，一步一个脚印地走好每步路，是时候推一把自己了。找回自己，找回自信，找回属于我的夏天。",-1)])])}const h=a(l,[["render",r]]);export{m as __pageData,h as default};
